import Testing
import Foundation
import Combine
import OpenMDict
@testable import OpenMDictKit

/// The lookup and search paths of the view models (Tests/Fixtures/fallbacks.mdx
/// and casesensitive.mdx, regenerated by make-fixture.py). The dictionaries
/// are opened with `MDictSidecarCache` as the process has it (no cache
/// directory under `swift test`); the suite sets none of its state, which
/// the suites of OpenMDictTests that do would see.
@Suite(.serialized)
@MainActor
struct MDictLookupTests {

    static var fixturesDirectory: URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()   // OpenMDictKitTests/
            .deletingLastPathComponent()   // Tests/
            .appendingPathComponent("Fixtures", isDirectory: true)
    }

    static func dictionary(_ fixture: String, headwordLanguage: String?) async throws -> MDict {
        let path = fixturesDirectory.appendingPathComponent(fixture).path
        let id = try #require(MDictReader.loadMetadata(from: path)?.headerSHA256)
        let dict = MDict(path: path, id: id, mddPaths: [])
        dict.headwordLanguage = headwordLanguage
        try await dict.load()
        return dict
    }

    /// Every emission of `publisher`, which must complete. Collected with
    /// `sink` (unlimited demand, as the app subscribes); the collector's
    /// closures are not main-actor-isolated, as Combine calls them on the
    /// threads the searches finish on.
    static func emissions(_ publisher: AnyPublisher<[WordSearchResult], Never>) async -> [[WordSearchResult]] {
        let collector = EmissionCollector()
        collector.subscribe(publisher)
        return await collector.completed()
    }

    final class EmissionCollector: @unchecked Sendable {
        private let lock = NSLock()
        private var emissions: [[WordSearchResult]] = []
        private var finished = false
        private var continuation: CheckedContinuation<[[WordSearchResult]], Never>?
        private var cancellable: AnyCancellable?

        func subscribe(_ publisher: AnyPublisher<[WordSearchResult], Never>) {
            cancellable = publisher.sink(
                receiveCompletion: { [self] _ in finish() },
                receiveValue: { [self] results in
                    lock.lock(); emissions.append(results); lock.unlock()
                })
        }

        private func finish() {
            lock.lock()
            finished = true
            let waiting = continuation
            continuation = nil
            let all = emissions
            lock.unlock()
            waiting?.resume(returning: all)
        }

        func completed() async -> [[WordSearchResult]] {
            await withCheckedContinuation { next in
                lock.lock()
                if finished {
                    let all = emissions
                    lock.unlock()
                    next.resume(returning: all)
                } else {
                    continuation = next
                    lock.unlock()
                }
            }
        }
    }

    @Test("lookup honours the headword language and the fallbacks asked for")
    func lookup() async throws {
        let german = try await Self.dictionary("fallbacks.mdx", headwordLanguage: "DE")
        #expect(german.lookup("machte")?.key == "machen")
        #expect(german.lookup("machte")?.fallback == .inflection(lemma: "machen"))
        #expect(german.lookup("blorpte")?.key == "blorpen")
        #expect(german.lookup("machte", fallbacks: .none) == nil)
        #expect(german.lookup("Machen", fallbacks: .none)?.key == "machen")
        #expect(german.lookup("ｍａｃｈｅｎ", fallbacks: .width)?.fallback == .widthFolded)
        #expect(german.lookup("ｍａｃｈｔｅ", fallbacks: .width) == nil)
        #expect(german.lookup("ｍａｃｈｔｅ")?.key == "machen")

        // A French dictionary undoes no English or German inflection. Its
        // diacritic index is not built on the main actor: the first lookup
        // that needs it starts the build in the background and misses
        // ("blorpte" is no key under any fallback); once the index is
        // there, "machte" finds its key by its diacritics.
        let french = try await Self.dictionary("fallbacks.mdx", headwordLanguage: "FR")
        #expect(french.lookup("blorpte") == nil)
        var found: MDictWordEntry?
        for _ in 0..<300 {
            found = french.lookup("machte")
            if found != nil { break }
            try await Task.sleep(nanoseconds: 10_000_000)
        }
        #expect(found?.key == "Mächte")
        #expect(found?.fallback == .diacriticInsensitive)
        #expect(french.lookup("blorpte") == nil)
    }

    @Test("A group's word list adds fallback rows only when no dictionary has a direct one")
    func groupSearchTwoPasses() async throws {
        let fallbacks = try await Self.dictionary("fallbacks.mdx", headwordLanguage: "DE")
        let caseSensitive = try await Self.dictionary("casesensitive.mdx", headwordLanguage: "DE")
        let group = MDicts([fallbacks, caseSensitive])

        // "mull": a direct key in one dictionary; the other's "Müller",
        // which only folding finds, stays out.
        let direct = await Self.emissions(group.lookupPublisher(prefix: "mull", limit: 20))
        let directFinal = try #require(direct.last)
        #expect(directFinal.map(\.word) == ["Mull"])
        #expect(directFinal.allSatisfy { $0.fallback == nil })
        #expect(direct.allSatisfy { $0.allSatisfy { $0.fallback == nil } })

        // "mulle": no dictionary has a direct key, so both contribute folded rows.
        let folded = await Self.emissions(group.lookupPublisher(prefix: "mulle", limit: 20))
        let foldedFinal = try #require(folded.last)
        #expect(foldedFinal.map(\.word) == ["Müller", "Müller"])
        #expect(Set(foldedFinal.map(\.dictId)) == [fallbacks.id, caseSensitive.id])
        #expect(foldedFinal.allSatisfy { $0.fallback == .diacriticInsensitive })

        // A full-width prefix: no dictionary has a direct key; each reports
        // the fallback that found its rows (the case-sensitive dictionary
        // has no "mull…", so folding finds its "Müller").
        let wide = await Self.emissions(group.lookupPublisher(prefix: "ｍｕｌｌ", limit: 20))
        let wideFinal = try #require(wide.last)
        #expect(wideFinal.map(\.word) == ["Mull", "Müller"])
        #expect(wideFinal.map(\.fallback) == [.widthFolded, .diacriticInsensitive])
        // A miss stays empty.
        let nothing = await Self.emissions(group.lookupPublisher(prefix: "zzzz", limit: 20))
        #expect(nothing.last?.isEmpty == true)

        // A single dictionary's publisher flags its fallback rows too.
        let single = await Self.emissions(fallbacks.lookupPublisher(prefix: "αθη", limit: 20))
        #expect(single.last?.map(\.word) == ["Ἀθῆναι"])
        #expect(single.last?.first?.fallback == .diacriticInsensitive)
        let singleDirect = await Self.emissions(fallbacks.lookupPublisher(prefix: "αθη", limit: 20, fallbacks: .none))
        #expect(singleDirect.last?.isEmpty == true)
    }
}
